import{_ as t,o as a,c as i,ag as o}from"./chunks/framework.8tqBsFWt.js";const u=JSON.parse('{"title":"Vendors & Liabilities","description":"","frontmatter":{},"headers":[],"relativePath":"reference/concepts/vendors.md","filePath":"reference/concepts/vendors.md"}'),s={name:"reference/concepts/vendors.md"};function n(r,e,l,d,c,p){return a(),i("div",null,[...e[0]||(e[0]=[o(`<h1 id="vendors-liabilities" tabindex="-1">Vendors &amp; Liabilities <a class="header-anchor" href="#vendors-liabilities" aria-label="Permalink to &quot;Vendors &amp; Liabilities&quot;">​</a></h1><p>Vendors are external contractors or agencies tracked in VERA. Liabilities are fixed payment commitments to those vendors.</p><hr><h2 id="vendor-users" tabindex="-1">Vendor users <a class="header-anchor" href="#vendor-users" aria-label="Permalink to &quot;Vendor users&quot;">​</a></h2><p>A vendor is a user with <code>employment_type = &quot;vendor&quot;</code>.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>add_user name=&quot;Dev House X&quot; employment_type=&quot;vendor&quot;</span></span></code></pre></div><p>Vendor users are like regular users in the system — they appear in <code>list_users</code>, can be allocated to projects, and have time logged against them. The difference is:</p><ol><li><strong>PMs log hours on their behalf</strong> — vendor users don&#39;t message the bot themselves</li><li><strong>Cost is typically governed by a liability</strong> rather than an hourly rate</li><li><strong>Revenue is the same as direct labor</strong> — hours × billing_rate</li></ol><hr><h2 id="liabilities" tabindex="-1">Liabilities <a class="header-anchor" href="#liabilities" aria-label="Permalink to &quot;Liabilities&quot;">​</a></h2><p>A <strong>liability</strong> is a fixed payment commitment to a vendor on a specific project.</p><p>Example: &quot;We agreed to pay Dev House X $5,000 to build the authentication module on Project Rambo.&quot;</p><p>This is recorded as a liability with:</p><ul><li><code>vendor_user_id</code> — Dev House X&#39;s user ID</li><li><code>project_id</code> — Project Rambo</li><li><code>agreed_amount</code> — $5,000</li><li><code>description</code> — &quot;Authentication module development&quot;</li></ul><h3 id="why-liabilities-exist" tabindex="-1">Why liabilities exist <a class="header-anchor" href="#why-liabilities-exist" aria-label="Permalink to &quot;Why liabilities exist&quot;">​</a></h3><p>Without a liability, VERA calculates vendor cost as <code>hours × hourly_cost</code>. But for fixed-fee vendor engagements, that&#39;s wrong — you&#39;ve agreed to pay $5,000 regardless of how many hours are logged.</p><p><strong>A liability overrides the hourly calculation entirely.</strong> When a liability is active for vendor X on project Y, the cost for that vendor on that project is <code>agreed_amount</code>, not <code>hours × rate</code>. The two methods are never mixed.</p><h3 id="revenue-still-comes-from-hours" tabindex="-1">Revenue still comes from hours <a class="header-anchor" href="#revenue-still-comes-from-hours" aria-label="Permalink to &quot;Revenue still comes from hours&quot;">​</a></h3><p>Liabilities only affect <strong>cost</strong>. Revenue is still recognised from time entries in the normal way (hours × billing_rate for T&amp;M, or percentage-of-completion for Fixed Price).</p><hr><h2 id="liability-lifecycle" tabindex="-1">Liability lifecycle <a class="header-anchor" href="#liability-lifecycle" aria-label="Permalink to &quot;Liability lifecycle&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>create_liability → active</span></span>
<span class="line"><span>       ↓</span></span>
<span class="line"><span>  cancel_liability → cancelled (not deleted)</span></span></code></pre></div><p>Cancelled liabilities are kept for audit trail. When listing liabilities, filter by <code>status = &quot;active&quot;</code> to see open commitments only.</p><hr><h2 id="permissions" tabindex="-1">Permissions <a class="header-anchor" href="#permissions" aria-label="Permalink to &quot;Permissions&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Action</th><th>Owner</th><th>Manager</th><th>User</th></tr></thead><tbody><tr><td>Create liability</td><td>✅</td><td>❌</td><td>❌</td></tr><tr><td>View liabilities</td><td>✅ (all)</td><td>✅ (own projects)</td><td>❌</td></tr><tr><td>Cancel liability</td><td>✅</td><td>❌</td><td>❌</td></tr></tbody></table><hr><h2 id="p-l-cost-rule-vendor-summary" tabindex="-1">P&amp;L cost rule (vendor summary) <a class="header-anchor" href="#p-l-cost-rule-vendor-summary" aria-label="Permalink to &quot;P&amp;L cost rule (vendor summary)&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>For vendor X on project Y:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  If active liability exists:</span></span>
<span class="line"><span>    cost = liability.agreed_amount</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  Else:</span></span>
<span class="line"><span>    cost = hours_logged × hourly_cost (from Rate History, effective on entry date)</span></span></code></pre></div><p>This rule is applied when calculating project cost and margin in <code>generate_monthly_report</code> and the reporting sheet&#39;s financial tabs.</p><hr><h2 id="common-vendor-workflow" tabindex="-1">Common vendor workflow <a class="header-anchor" href="#common-vendor-workflow" aria-label="Permalink to &quot;Common vendor workflow&quot;">​</a></h2><ol><li><strong>Add the vendor</strong>: <code>add_user</code> with <code>employment_type=&quot;vendor&quot;</code></li><li><strong>Create a liability</strong>: <code>create_liability</code> with the agreed amount and description</li><li><strong>PM logs hours</strong>: <code>log_time</code> with the vendor&#39;s user ID — this tracks delivery against the engagement</li><li><strong>View cost</strong>: The liability&#39;s <code>agreed_amount</code> appears as cost in financial reports, regardless of hours logged</li></ol><p>If the engagement grows beyond the original liability, cancel the old one and create a new one with the updated amount.</p>`,34)])])}const m=t(s,[["render",n]]);export{u as __pageData,m as default};
